style.css:
/* Cyber-Themed Background */
@namespace url("http://www.w3.org/1999/xhtml");
@-moz-document domain("miruro.tv") {
/* Set a cyber-themed background image */
    body {
        background: url('https://img.freepik.com/free-photo/illustration-anime-character-rain_23-2151394670.jpg?semt=ais_hybrid') no-repeat center center fixed !important;
        background-size: cover !important;
        font-family: 'Arial', 'Helvetica', sans-serif !important; /* Change the font to sans-serif */
        color: #fff !important;
    }

    /* Sidebar Styling */
    .sidebar {
        background-color: rgba(0, 0, 0, 0.8) !important; /* Transparent black for better contrast */
        color: #fff !important;
    }

    .sidebar a {
        color: #fff !important;
        text-decoration: none !important;
    }

    .sidebar a:hover {
        color: #1e90ff !important; /* Bright blue on hover for a cyber effect */
    }

    /* Main Content Text */
    main, .content, .title, .description {
        font-family: 'Arial', 'Helvetica', sans-serif !important;
        color: #fff !important;
    }

    /* Buttons */
    button, .btn {
        background-color: #1e90ff !important; /* Bright blue cyber button */
        border: none !important;
        color: #fff !important;
        font-family: 'Arial', sans-serif !important;
        padding: 10px 20px !important;
        border-radius: 5px !important;
        cursor: pointer !important;
        transition: background-color 0.3s ease !important;
    }

    button:hover, .btn:hover {
        background-color: #00bfff !important; /* Lighter blue on hover */
    }

    /* Genre Buttons */
    .genre-button {
        background-color: rgba(255, 255, 255, 0.1) !important;
        color: #fff !important;
        border: 1px solid #fff !important;
        border-radius: 5px !important;
        padding: 5px 10px !important;
        transition: all 0.3s ease !important;
    }

    .genre-button:hover {
        background-color: rgba(255, 255, 255, 0.3) !important;
        color: #1e90ff !important;
    }

    /* Header and Footer */
    header, footer {
        background-color: rgba(0, 0, 0, 0.8) !important;
        font-family: 'Arial', 'Helvetica', sans-serif !important;
        color: #fff !important;
    }
}
